typedef struct {
    int rank;   // 0:null 1:one pair 2:two pair 3:three card 4:straight 5:full house 6:four card
    int v[5];   // tie breakers, lexicographically larger is better
} HandEval;

static int cmp_desc(const void *a, const void *b) {
    return (*(int *)b) - (*(int *)a);
}

static int cmp_asc(const void *a, const void *b) {
    return (*(int *)a) - (*(int *)b);
}

static HandEval eval_hand(int a[5]) {
    HandEval e;
    int i, j;
    int cnt[14] = {0}; // 1..13
    int vals[5];
    int distinct = 0;
    int four = 0, three = 0;
    int pairs[2], npairs = 0;

    for (i = 0; i < 5; i++) {
        vals[i] = a[i];
        cnt[a[i]]++;
    }

    for (i = 1; i <= 13; i++) {
        if (cnt[i]) distinct++;
        if (cnt[i] == 4) four = i;
        else if (cnt[i] == 3) three = i;
        else if (cnt[i] == 2) pairs[npairs++] = i;
    }

    for (i = 0; i < 5; i++) e.v[i] = 0;

    if (four) {
        e.rank = 6;
        e.v[0] = four;
        for (i = 1; i <= 13; i++) if (cnt[i] == 1) e.v[1] = i;
        return e;
    }

    if (three && npairs == 1) {
        e.rank = 5;
        e.v[0] = three;
        e.v[1] = pairs[0];
        return e;
    }

    // straight: 5 distinct consecutive cards, A can be low (1,2,3,4,5) or high (10,11,12,13,1)
    if (distinct == 5) {
        int b[5], ok = 1;
        for (i = 0; i < 5; i++) b[i] = vals[i];
        qsort(b, 5, sizeof(int), cmp_asc);

        for (i = 1; i < 5; i++) {
            if (b[i] != b[0] + i) {
                ok = 0;
                break;
            }
        }
        if (ok) {
            e.rank = 4;
            e.v[0] = b[4]; // highest card
            return e;
        }

        // A high straight: 1,10,11,12,13
        if (b[0] == 1 && b[1] == 10 && b[2] == 11 && b[3] == 12 && b[4] == 13) {
            e.rank = 4;
            e.v[0] = 14; // higher than K, represents A-high straight
            return e;
        }
    }

    if (three) {
        e.rank = 3;
        e.v[0] = three;
        j = 1;
        for (i = 13; i >= 1; i--) {
            if (cnt[i] == 1) e.v[j++] = i;
        }
        return e;
    }

    if (npairs == 2) {
        int hi = pairs[0] > pairs[1] ? pairs[0] : pairs[1];
        int lo = pairs[0] > pairs[1] ? pairs[1] : pairs[0];
        e.rank = 2;
        e.v[0] = hi;
        e.v[1] = lo;
        for (i = 1; i <= 13; i++) if (cnt[i] == 1) e.v[2] = i;
        return e;
    }

    if (npairs == 1) {
        e.rank = 1;
        e.v[0] = pairs[0];
        j = 1;
        for (i = 13; i >= 1; i--) {
            if (cnt[i] == 1) e.v[j++] = i;
        }
        return e;
    }

    e.rank = 0;
    qsort(vals, 5, sizeof(int), cmp_desc);
    for (i = 0; i < 5; i++) e.v[i] = vals[i];
    return e;
}

static int better(HandEval a, HandEval b) {
    int i;
    if (a.rank != b.rank) return a.rank > b.rank;
    for (i = 0; i < 5; i++) {
        if (a.v[i] != b.v[i]) return a.v[i] > b.v[i];
    }
    return 0;
}

static const char *name_of_rank(int rank) {
    switch (rank) {
        case 0: return "null";
        case 1: return "one pair";
        case 2: return "two pair";
        case 3: return "three card";
        case 4: return "straight";
        case 5: return "full house";
        case 6: return "four card";
    }
    return "";
}

