    static String evaluate(int[] cards) {
        // Count frequencies
        Map<Integer, Integer> freq = new HashMap<>();
        for (int c : cards) {
            freq.merge(c, 1, Integer::sum);
        }

        List<Integer> counts = new ArrayList<>(freq.values());
        Collections.sort(counts, Collections.reverseOrder());

        // Check four card
        if (counts.get(0) == 4) return "four card";

        // Check full house
        if (counts.get(0) == 3 && counts.get(1) == 2) return "full house";

        // Check straight
        if (isStraight(cards)) return "straight";

        // Check three card
        if (counts.get(0) == 3) return "three card";

        // Check two pair
        if (counts.get(0) == 2 && counts.get(1) == 2) return "two pair";

        // Check one pair
        if (counts.get(0) == 2) return "one pair";

        return "null";
    }

    static boolean isStraight(int[] cards) {
        int[] sorted = cards.clone();
        Arrays.sort(sorted);

        // Check normal straight
        boolean normal = true;
        for (int i = 1; i < 5; i++) {
            if (sorted[i] != sorted[i-1] + 1) {
                normal = false;
                break;
            }
        }
        if (normal) return true;

        // Check Ace-high straight: A treated as 14
        // Cards would be 10,11,12,13,1 → sorted: 1,10,11,12,13
        // Replace 1 with 14 and re-sort
        int[] modified = cards.clone();
        boolean hasAce = false;
        for (int i = 0; i < 5; i++) {
            if (modified[i] == 1) {
                modified[i] = 14;
                hasAce = true;
            }
        }
        if (hasAce) {
            Arrays.sort(modified);
            boolean aceHigh = true;
            for (int i = 1; i < 5; i++) {
                if (modified[i] != modified[i-1] + 1) {
                    aceHigh = false;
                    break;
                }
            }
            if (aceHigh) return true;
        }

        return false;
    }
}

