using namespace std;

// Function to determine the rank of a hand
// Returns: 0 = null, 1 = one pair, 2 = two pair, 3 = three card, 
//          4 = straight, 5 = full house, 6 = four card
int getHandRank(const vector<int>& hand) {
    // Count occurrences of each value
    map<int, int> counts;
    for (int card : hand) {
        counts[card]++;
    }

    // Check for four of a kind
    for (const auto& p : counts) {
        if (p.second == 4) return 6;
    }

    // Check for full house
    bool hasThree = false, hasPair = false;
    for (const auto& p : counts) {
        if (p.second == 3) hasThree = true;
        if (p.second == 2) hasPair = true;
    }
    if (hasThree && hasPair) return 5;

    // Check for straight
    vector<int> sorted = hand;
    sort(sorted.begin(), sorted.end());

    // Normal straight check (including A-2-3-4-5)
    bool isStraight = true;
    for (int i = 0; i < 4; i++) {
        if (sorted[i+1] - sorted[i] != 1) {
            isStraight = false;
            break;
        }
    }

    // Check for A-K-Q-J-10 (Ace as high)
    if (!isStraight && sorted[0] == 1 && sorted[1] == 10 && sorted[2] == 11 && sorted[3] == 12 && sorted[4] == 13) {
        isStraight = true;
    }

    if (isStraight) return 4;

    // Check for three of a kind
    if (hasThree) return 3;

    // Check for two pair
    int pairCount = 0;
    for (const auto& p : counts) {
        if (p.second == 2) pairCount++;
    }
    if (pairCount == 2) return 2;

    // Check for one pair
    if (pairCount == 1) return 1;

    return 0;
}

string handRankToString(int rank) {
    switch (rank) {
        case 0: return "null";
        case 1: return "one pair";
        case 2: return "two pair";
        case 3: return "three card";
        case 4: return "straight";
        case 5: return "full house";
        case 6: return "four card";
        default: return "";
    }
}

