            if (sorted_cards[i] != sorted_cards[i-1] + 1) { ok = false; break; }
        }
        if (ok) straight = true;

        // Ace high: A,10,11,12,13 -> sorted: 1,10,11,12,13
        if (!straight && sorted_cards[0] == 1 && sorted_cards[1] == 10 &&
            sorted_cards[2] == 11 && sorted_cards[3] == 12 && sorted_cards[4] == 13) {
            straight = true;
        }

        // Determine best hand
        string result;
        if (four) result = "four card";
        else if (fullhouse) result = "full house";
        else if (straight) result = "straight";
        else if (three) result = "three card";
        else if (twopair) result = "two pair";
        else if (onepair) result = "one pair";
        else result = "null";

        cout << result << endl;
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

string judge(const vector<int>& a) {
    map<int, int> cnt;
    for (int x : a) cnt[x]++;

    vector<int> freq;
    for (auto &p : cnt) freq.push_back(p.second);
    sort(freq.begin(), freq.end());

    bool four = false, three = false;
    int pairs = 0;
    for (int f : freq) {
        if (f == 4) four = true;
        if (f == 3) three = true;
        if (f == 2) pairs++;
    }

    bool straight = false;
    {
        vector<int> b = a;
        sort(b.begin(), b.end());
        bool ok = true;
        for (int i = 1; i < 5; i++) {
            if (b[i] != b[i - 1] + 1) ok = false;
        }
        if (ok) straight = true;

        // Ace high case: 1,10,11,12,13 is NOT straight here.
        // Ace can be low only in A,2,3,4,5 or high at the end in 10,11,12,13,1?
        // Problem statement says Ace treated as both high and low at the ends,
        // so check 10,11,12,13,1 as straight too.
        vector<int> c = a;
        for (int &x : c) if (x == 1) x = 14;
        sort(c.begin(), c.end());
        ok = true;
        for (int i = 1; i < 5; i++) {
            if (c[i] != c[i - 1] + 1) ok = false;
        }
        if (ok) straight = true;
    }

    if (four) return "four card";
    if (three && pairs == 1) return "full house";
    if (straight) return "straight";
    if (three) return "three card";
    if (pairs == 2) return "two pair";
    if (pairs == 1) return "one pair";
    return "null";
}

